create or replace function public.dreem_ingest_driver_offline_event(p_school_id uuid,p_trip_id uuid,p_event_type text,p_stop_id uuid,p_student_id uuid,p_note text,p_captured_at timestamptz,p_device_id text,p_payload_digest text,p_idempotency_key text)returns table(trip_id uuid,trip_status text) language plpgsql security definer set search_path='' as $$declare v_user uuid:=(select auth.uid());v_driver_id uuid;v_trip_school uuid;begin if v_user is null then raise exception 'Authentication is required';end if;select t.school_id,d.user_id into v_trip_school,v_driver_id from public.dreem_transport_trips t join public.dreem_transport_drivers d on d.id=t.driver_id where t.id=p_trip_id;if v_trip_school is null or v_trip_school<>p_school_id or v_driver_id<>v_user then raise exception 'Offline driver event does not belong to this active driver assignment';end if;if p_captured_at>now()+interval '5 minutes'then raise exception 'Offline capture time is invalid';end if;if p_captured_at<now()-interval '7 days'then raise exception 'Offline journey event is too old to ingest automatically';end if;if length(trim(coalesce(p_device_id,'')))<3 or length(trim(coalesce(p_payload_digest,'')))<32 then raise exception 'Offline device and integrity evidence are required';end if;return query select * from public.dreem_progress_transport_trip(p_trip_id,p_event_type,p_stop_id,p_student_id,p_note,jsonb_build_object('capture','offline_driver_outbox','captured_at',p_captured_at,'received_at',now(),'device_id',p_device_id,'payload_digest',p_payload_digest),p_idempotency_key);insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(p_school_id,v_user,'transport.offline_event_ingested','transport_trip',p_trip_id,jsonb_build_object('event_type',p_event_type,'captured_at',p_captured_at,'device_id',p_device_id,'payload_digest',p_payload_digest));end;$$;
revoke all on function public.dreem_ingest_driver_offline_event(uuid,uuid,text,uuid,uuid,text,timestamptz,text,text,text) from public;grant execute on function public.dreem_ingest_driver_offline_event(uuid,uuid,text,uuid,uuid,text,timestamptz,text,text,text) to authenticated;